import type { PerformanceAndBreakdownWaterfallData } from '../../types';
import { getPerformanceAndBreakdownBrandImage } from '../assets/brandImageUrls';
import { PerformanceAndBreakdownDeepDiveSkuComparisonLines } from './deepDiveComparisonLines';
import { buildPerformanceAndBreakdownDeepDiveDrillComparisonLines } from './deepDiveLayerComparisonLines';
import {
  buildPerformanceAndBreakdownDeepDiveImagesData,
  PERFORMANCE_AND_BREAKDOWN_DEEP_DIVE_WATERFALL_LE_VALUE,
  PERFORMANCE_AND_BREAKDOWN_DEEP_DIVE_WATERFALL_PREFIX,
} from './deepDiveWaterfallPrefix';

export const PERFORMANCE_AND_BREAKDOWN_DEEP_DIVE_SKU_LABELS_TEMPLATE = [
  '{subBrand} bottle 000ml',
  '{subBrand} long neck 000ml',
  '{subBrand} can 000ml',
  '{subBrand} bottle 600ml',
] as const;

const PERFORMANCE_AND_BREAKDOWN_DEEP_DIVE_SKU_VALUES = [
  0.9, 0.6, 0.5, 0.4,
] as const;

function buildSkuLabels(subBrandName: string): string[] {
  return PERFORMANCE_AND_BREAKDOWN_DEEP_DIVE_SKU_LABELS_TEMPLATE.map(
    (template) => template.replace('{subBrand}', subBrandName),
  );
}

interface BuildPerformanceAndBreakdownDeepDiveSkuMockParams {
  brandName: string;
  subBrandName: string;
  clickable?: boolean;
}

export function buildPerformanceAndBreakdownDeepDiveSkuMock({
  brandName,
  subBrandName,
  clickable = true,
}: BuildPerformanceAndBreakdownDeepDiveSkuMockParams): PerformanceAndBreakdownWaterfallData {
  const skus = buildSkuLabels(subBrandName);
  const skuValues = PERFORMANCE_AND_BREAKDOWN_DEEP_DIVE_SKU_VALUES.slice(
    0,
    skus.length,
  );
  const formattedSkuValues = skuValues.map((value) => `+${value}`);
  const le = PERFORMANCE_AND_BREAKDOWN_DEEP_DIVE_WATERFALL_LE_VALUE;
  const lastIndex =
    PERFORMANCE_AND_BREAKDOWN_DEEP_DIVE_WATERFALL_PREFIX.labels.length +
    skus.length;
  const entityStartIndex =
    PERFORMANCE_AND_BREAKDOWN_DEEP_DIVE_WATERFALL_PREFIX.labels.length;
  const anchor = {
    src: getPerformanceAndBreakdownBrandImage(brandName).src,
    alt: subBrandName,
  };
  const comparisonLines =
    skus.length === 4
      ? PerformanceAndBreakdownDeepDiveSkuComparisonLines
      : buildPerformanceAndBreakdownDeepDiveDrillComparisonLines(
          PERFORMANCE_AND_BREAKDOWN_DEEP_DIVE_WATERFALL_PREFIX.labels.length +
            skus.length +
            1,
        );

  return {
    values: [
      ...PERFORMANCE_AND_BREAKDOWN_DEEP_DIVE_WATERFALL_PREFIX.values,
      ...skuValues,
      le,
    ],
    labels: [
      ...PERFORMANCE_AND_BREAKDOWN_DEEP_DIVE_WATERFALL_PREFIX.labels,
      ...skus,
      "'26 LE",
    ],
    formattedData: [
      [
        ...PERFORMANCE_AND_BREAKDOWN_DEEP_DIVE_WATERFALL_PREFIX.formatted,
        ...formattedSkuValues,
        String(le),
      ],
    ],
    specialIndexes: { first: 0, last: lastIndex },
    disabledIndexes: clickable
      ? [
          ...PERFORMANCE_AND_BREAKDOWN_DEEP_DIVE_WATERFALL_PREFIX.disabledIndexes,
          lastIndex,
        ]
      : Array.from({ length: lastIndex + 1 }, (_, index) => index),
    clickableIndexes: clickable
      ? Array.from(
          { length: skus.length },
          (_, index) => entityStartIndex + index,
        )
      : [],
    filterValues: [
      ...PERFORMANCE_AND_BREAKDOWN_DEEP_DIVE_WATERFALL_PREFIX.filterValues,
      ...skus,
      null,
    ],
    images: {
      data: buildPerformanceAndBreakdownDeepDiveImagesData(anchor, skus),
    },
    comparisonLine: { data: comparisonLines },
  };
}

/** Brahma Duplo Malte fixture for tests and default sku map entry. */
export const PerformanceAndBreakdownDeepDiveSkuWaterfallMock =
  buildPerformanceAndBreakdownDeepDiveSkuMock({
    brandName: 'Brahma',
    subBrandName: 'Brahma Duplo Malte',
  });

export function buildPerformanceAndBreakdownDeepDiveSkuTerminalMock(
  base: PerformanceAndBreakdownWaterfallData,
): PerformanceAndBreakdownWaterfallData {
  return {
    ...base,
    clickableIndexes: [],
    disabledIndexes: base.labels.map((_, index) => index),
  };
}
